-- Wheels / saddle / seatpost: render layers, close-up views and part photos
update public.products p set customization = p.customization
  || jsonb_build_object('preview', $t$pg_name:{colour};F-nondrive;{wheels};F-drive;{cockpit};{seatpost}-{saddle}/2027_4480_cfr-Di2_3D_Aeroad$t$)
  || jsonb_build_object('steps', (
    select jsonb_agg(
      case when patch.v is null then s
      else s || jsonb_build_object('view', patch.v->'view', 'options', (
        select jsonb_agg(o || coalesce(patch.v->'options'->(o->>'id'), '{}') order by n)
        from jsonb_array_elements(s->'options') with ordinality x(o, n)))
      end order by i)
    from jsonb_array_elements(p.customization->'steps') with ordinality t(s, i)
    left join lateral (select ($p${"wheels": {"view": "_WS_24", "options": {"arc1100-55": {"render": "20027612", "image": "https://dma.canyon.com/image/upload/w_240,h_240,c_fit/f_auto/q_auto/v1753702807/2025_FULL_GEAR-COM_CUSTOM-WHEELS-DT-Swiss-ARC1100db55-4039_20027612_-_customization_khh6w0"}, "arc1100-65": {"render": "20032414", "image": "https://dma.canyon.com/image/upload/w_240,h_240,c_fit/f_auto/q_auto/v1782332162/2026_FULL_GEAR-COM_CUSTOM-WHEELS-DT-Swiss-ARC-1100-65mm-4480_20032414_-_customization_3D_kfzjt1"}, "zipp-454": {"render": "20032416", "image": "https://dma.canyon.com/image/upload/w_240,h_240,c_fit/f_auto/q_auto/v1782368585/2026_FULL_GEAR-COM_CUSTOM-WHEELS-Zipp454NSW-PirelliP-ZERO-TLR-RS_20032416_-_customization_3D_r6wsph"}, "scope-6": {"render": "20034318", "image": "https://dma.canyon.com/image/upload/w_240,h_240,c_fit/f_auto/q_auto/v1782332495/2026_FULL_GEAR-COM_CUSTOM-WHEELS-Scope-A6-4480_20034318_-_customization_3D_rjdykl"}}}, "saddle": {"view": "_S_24", "options": {"slr-carbon": {"render": "20027914", "image": "https://dma.canyon.com/image/upload/w_240,h_240,c_fit/f_auto/q_auto/v1775660741/2026_FULL_GEAR-COM_CUSTOM-SADDLES-Selle-Italia-SLR-Carbon_20027914_-_customization_3D_x08rgg"}, "slr-3d": {"render": "20027912", "image": "https://dma.canyon.com/image/upload/w_240,h_240,c_fit/f_auto/q_auto/v1775660741/2026_FULL_GEAR-COM_CUSTOM-SADDLES-Selle-Italia-SLR-3D-Carbon_20027912_-_customization_3D_l2gzbj"}, "slr-tekno": {"render": "20018092", "image": "https://dma.canyon.com/image/upload/w_240,h_240,c_fit/f_auto/q_auto/v1738337830/20018092_b3h6zy"}}}, "seatpost": {"view": "_S_24", "options": {"sp105": {"render": "20028850", "image": "https://dma.canyon.com/image/upload/w_240,h_240,c_fit/f_auto/q_auto/v1782326865/2026_FULL_GEAR-COM_CUSTOM-SEATPOST-SP0105-Aero_200475_-_customization_3D_aysrv2"}, "sp093": {"render": "20028846", "image": "https://dma.canyon.com/image/upload/w_240,h_240,c_fit/f_auto/q_auto/v1782326864/2026_FULL_GEAR-COM_CUSTOM-SEATPOST-SP0093-Comfort_200477_-_customization_3D_domgps"}}}}$p$::jsonb)->(s->>'key') as v) patch on true))
where slug = 'aeroad-cfr-di2-4480';
